INSERT INTO public.generic_medicines (generic_name, description, atc_code)
VALUES ('Phenylephrine', 'Used in the treatment of nasal congestion. Phenylephrine was originally approved by the FDA in 1952 as phenylephrine hydrochloride in combination with codeine phosphate and promethazine hydrochloride as active ingredients. Phenylephrine hydrochloride was approved by the FDA in 2012. This drug is most commonly found in brand mixtures used to alleviate cold and flu symptoms. On its own, the drug is found in nasal decongestants. In 2001, the EMA granted orphan designation for phenylephrine hydrochloride for the treatment of ileal pouch anal anastomosis related faecal incontinence .', NULL)
ON CONFLICT (generic_name) DO UPDATE SET description = EXCLUDED.description;

