INSERT INTO public.generic_medicines (generic_name, description, atc_code)
VALUES ('Ranitidine', 'Ranitidine was used (until its withdrawl in many countries in 2020) in the treatment of gastic ulcers, where blocking of H2 receptors reduces gastric acid secretion and ameliorates disease symptoms. At the beginning of April 2020 the FDA withdrew marketing authorisation for all ranitidine products, after excess levels of the hepatotoxic and carcinogenic chemical N-nitrosodimethylamine (NDMA) were detected in ranitidine medications . Mylan had voluntarily recalled prescription capsules for the same reason in January 2020. Other regulatory agencies also withdrew their marketing authosisations following this contamination problem.', NULL)
ON CONFLICT (generic_name) DO UPDATE SET description = EXCLUDED.description;

