INSERT INTO public.generic_medicines (generic_name, description, atc_code)
VALUES ('Zinc Pyrithione', 'Zinc pyrithione is an active component of topical treatments used to treat dandruff and seborrhoeic dermatitis. Such treatments are available in many countries from pharmacies without a prescription, as an over-the-counter (OTC) medication. However, the use of zinc pyrithione has been banned by the European Commission since 2021 because of concerns over reproductive toxicity.', NULL)
ON CONFLICT (generic_name) DO UPDATE SET description = EXCLUDED.description;

INSERT INTO public.generic_medicines (generic_name, description, atc_code)
VALUES ('Retigabine', 'Retigabine was approved to treat intractable partial-onset epileptic seizures. Use of retigabine was discontinued in 2017 due to serious side-effects including urinary retention and blue discoloration in melanin-containing tissues. The poor selectivity of retigabine among Kv7.2-Kv7.5 channels, and issues around its metabolic degradation products are considered to contribute to these adverse events . Channel activators with improved selectivity for Kv7.2/Kv7.3 and enhanced metabolic stability are being developed and investigated .', NULL)
ON CONFLICT (generic_name) DO UPDATE SET description = EXCLUDED.description;

