INSERT INTO public.generic_medicines (generic_name, description, atc_code)
VALUES ('Triamcinolone', 'Triamcinolone is used for its antiinflammatory or immunosuppressive actions in many conditions. For example, oral triamcinolone is used to treat conditions such as allergic disorders, skin conditions, ulcerative colitis, arthritis, lupus, psoriasis, and breathing disorders. This drug is also used topically as an anti-inflammatory and anti-pruritic agent. Injectable forms of the drug may be used to reduce intra-articular joint pain, stiffness and swelling associated with rheumatoid and osteoarthritic arthritis, bursitis, epicondylitis, and tenosynovitis.', NULL)
ON CONFLICT (generic_name) DO UPDATE SET description = EXCLUDED.description;

