INSERT INTO public.generic_medicines (generic_name, description, atc_code)
VALUES ('Drospirenone', 'Drospirenone is used in combination with estrogens (such as ethinylestradiol or estradiol) in many female contraceptive and hormone replacement therapy medications. Drospirenone may also be used to treat acne and severe forms of premenstrual syndrome. In June 2019, drospirenone (Slynd®) received FDA approval as the first progestin-only oral contraceptive pill with a 24 active/4 inactive tablet dosing regimen, and which provides a 24-hour missed pill window. The anti-mineralocorticoid activity of drospirenone means that it is contrindicated in women with conditions that predispose to hyperkalemia (e.g. renal or hepatic impairment, or adrenal insufficiency).', NULL)
ON CONFLICT (generic_name) DO UPDATE SET description = EXCLUDED.description;

