INSERT INTO public.generic_medicines (generic_name, description, atc_code)
VALUES ('Bumetanide', 'A loop diuretic use to treat edema associated with heart failure, hepatic and renal disease. Diuretics and autism spectrum disorder (ASD) Treatment of autistic children and adolescents with bumetanide (Phase 3 trial ) improves core ASD symptoms . The mechanism is proposed (at least in part) to reflect the effect that bumetanide exerts on intracellular neuronal chloride levels and the consequences of this on GABAergic networks. In preclinical models bumetanide decreases interacellular chloride levels and promotes GABAergic mediated hyperpolarisation (inhibition).', NULL)
ON CONFLICT (generic_name) DO UPDATE SET description = EXCLUDED.description;

