INSERT INTO public.generic_medicines (generic_name, description, atc_code)
VALUES ('Chloroquine', 'Chloroquine is one of the antimalarials listed in the World Health Organization''s Model List of Essential Medicines, with its recommended use restricted to the prevention and treatment of P. vivax infection in areas where resistance has not yet developed. It is also used off-label for other conditions/diseases, including treatment of autoimmune disorders (rheumatoid arthritis and lupus erythematosus), as an antiretroviral (HIV-1/AIDS and chikungunya fever) and as a radiosensitizing/chemosensitizing agent benefitting cancer therapies.', NULL)
ON CONFLICT (generic_name) DO UPDATE SET description = EXCLUDED.description;

