INSERT INTO public.generic_medicines (generic_name, description, atc_code)
VALUES ('Hydroxyurea', 'Approved as either hydroxyurea or hydroxycarbamide, this drug is used to treat melanoma, resistant chronic myelocytic leukemia, and recurrent, metastatic, or inoperable carcinoma of the ovary. In the US, the FDA has approved hydroxyurea to treat sickle cell anemia in adults, as shown by the presence of hemoglobin S. The FDA has subsequently granted orphan designation for the treatment of sickle cell disease in pediatric and young adult patient groups (2005-2015). The EMA granted hydroxyurea orphan designation as a treatment for sickle cell syndrome in 2003, and full approval for this indication was granted in 2019.', NULL)
ON CONFLICT (generic_name) DO UPDATE SET description = EXCLUDED.description;

