INSERT INTO public.generic_medicines (generic_name, description, atc_code)
VALUES ('Gilteritinib', 'The FDA granted Fast Track/Priority Review designation for the New Drug Application (NDA) that was submitted by the drug''s developer Astellas in June 2018. This led to full approval in November 2018, for the use of gilteritinib (Xospata®) as a therapy for patients with relapsed/refractory acute myeloid leukemia (AML) with a confirmed FLT3 mutation. Phase 1/2 clinical trial results were published by Perl et al. in 2017 . The EMA had granted gilteritinib orphan drug designation as a treatment for AML in January 2018 . In September 2019, following accelerated assessment, the EMA Committee for Medicinal Products for Human Use (CHMP) reported that they were minded to grant marketing authorisation for the same patient group as indicated by the FDA approval , and full approval was granted in October 2019.', NULL)
ON CONFLICT (generic_name) DO UPDATE SET description = EXCLUDED.description;

