INSERT INTO public.generic_medicines (generic_name, description, atc_code)
VALUES ('Elafibranor', 'Elafibranor was advanced into clinical development by Genfit, as a therapuetic for nonalcoholic steatohepatitis (NASH) . Phase 1/2 trials confirmed the potential efficacy of elafibranor, and specific adverse safety signals were not detected in these studies . Interim (futility) analysis of Phase 3 trial data, concluded that elafibranor was not better than placebo at improving NASH symptoms without worsening fibrosis, and development for NASH was terminated in mid-2020. However, elafibranor was repositioned as a treament for primary biliary cholangitis and was granted FDA approval for this indication in June 2024 , and EMA authorisation in Sepetmber 2024.', NULL)
ON CONFLICT (generic_name) DO UPDATE SET description = EXCLUDED.description;

